<?php

/*
 * AYU-1 · English texts of the product help (keys from catalog.php). Same format as es.php.
 */
return [
    'primeros-pasos' => ['title' => 'Getting started with GestiaHR', 'summary' => 'How to move around and where to find what you need.', 'body' => "GestiaHR brings together your organization's people data and the requests they make to Human Resources.\n\n- The sidebar groups the screens you can open according to your role and the modules your organization has.\n- The «Create» button in the top bar opens the most used forms.\n- The inbox collects what is waiting for your answer: approvals and tasks.\n- The help button opens this guide and the articles of the screen you are on.\n\nIf the help does not solve it, you can send a request to Human Resources from the portal."],
    'guia-administrador' => ['title' => 'Company administrator guide', 'summary' => 'What to set up first and how to keep the organization in order.', 'body' => "As an administrator you prepare the organization so the rest of the team can work smoothly.\n\n- Register the group's companies and their sites in Organization.\n- Create users, assign roles and review the permissions each role has in Settings.\n- Publish the approval flows before people start sending requests.\n- Review the organization's parameters and holiday calendars.\n\nSensitive changes are kept in the audit log, and the trash lets you recover what was archived by mistake."],
    'guia-rrhh' => ['title' => 'Human Resources guide', 'summary' => 'The employee lifecycle: hire, profile, changes, documents and termination.', 'body' => "Human Resources keeps each employee's profile, which is the source the other modules use.\n\n- Register a hire from «Create → Employee»; the system creates the employment and its first assignment.\n- Changes of job, manager or salary are recorded as movements with an effective date: nothing is overwritten.\n- The employee file keeps documents with versions and warns about expiry dates.\n- Requests from the portal reach your inbox and are resolved there.\n\nBefore a backdated change, check the profile timeline to see what will be affected."],
    'guia-jefe' => ['title' => 'Guide for managers', 'summary' => 'How to look after your team: requests, key dates and each person\'s data.', 'body' => "From My team you see the people who report to you and what they need from you.\n\n- In «Requests» you approve or reject your team's vacations, absences and other requests.\n- In «Dates» you find birthdays, anniversaries and the end of contracts or probation periods.\n- From each person's profile you can propose a movement or a new position.\n\nIf you are away, a delegation lets someone else handle your approvals during that time."],
    'guia-colaborador' => ['title' => 'Employee guide', 'summary' => 'What you can do from your portal, also on your phone.', 'body' => "Your portal brings together your data, your documents and your requests to Human Resources.\n\n- Check your personal and work data and ask for corrections.\n- Download your documents, your current contract and your certificates.\n- Request vacations or report an absence and follow its approval.\n- Send a request to Human Resources and get the answer in the same place.\n\nYou can install GestiaHR on your phone from your user menu."],
    'guia-auditor' => ['title' => 'Guide for auditors and accountants', 'summary' => 'What you can look up and how your access is recorded.', 'body' => "Your access is read-only: you see the information your role allows, without changing it.\n\n- The audit log shows who made each change, when, and the values before and after.\n- Exports are recorded with their reason.\n- Sensitive data only appears if your role has the field permission, and every read is kept in the access log."],
    'guia-aprobaciones-y-tareas' => ['title' => 'Approvals and tasks', 'summary' => 'How approval flows and the task inbox work.', 'body' => "Each request that needs it follows an approval flow published by the organization: levels, approvers and deadlines.\n\n- What waits for your decision appears in Approvals and in the inbox.\n- When rejecting, write the reason: the person receives it with the notice.\n- If the deadline passes, the flow can escalate or remind as configured.\n\nTasks are for internal to-dos: they have an owner, a priority and a due date."],
    'guia-colaboradores-y-legajo' => ['title' => 'Employees and the digital file', 'summary' => 'The 360 profile, effective-dated history and each person\'s documents.', 'body' => "The employee profile shows personal and work data, contracts, compensation, social security, payment accounts and documents in tabs.\n\n- Every data point with history has a start and end date: you can see how it was on any date.\n- Future changes are scheduled and apply on their own on that date.\n- The file sorts documents by folder and keeps all their versions.\n\nSensitive data, such as salary, is only visible to those with the field permission."],
    'guia-vacaciones-y-ausencias' => ['title' => 'Vacations and absences', 'summary' => 'Balances, requests, medical leave and statutory leave.', 'body' => "The system calculates each person's vacation balance from the policy and the parameters in force; do not calculate it by hand.\n\n- When requesting vacations you see the days that will be deducted before sending.\n- Absences are recorded by type; some require supporting documents.\n- Long medical leaves open a subsidy case for follow-up.\n\nThe team calendar shows who will be away so you can plan ahead."],
    'pantalla-inicio' => ['title' => 'Your home', 'summary' => 'What the home cards show.', 'body' => "Your home changes with your role: it shows your pending items, notices and shortcuts to what you use most.\n\nIf you have several roles, you can switch views at the top of the home page."],
    'pantalla-pendientes' => ['title' => 'Inbox', 'summary' => 'Everything waiting for your answer in one place.', 'body' => 'The inbox collects approvals, tasks and requests assigned to you. Open them from here to resolve them without searching each module.'],
    'pantalla-avisos' => ['title' => 'Notices', 'summary' => 'The notifications you received in the system.', 'body' => 'Notices sent to you by the system are kept here. Mark them as read and choose the channel for each type in My notifications.'],
    'pantalla-aprobaciones' => ['title' => 'Approvals', 'summary' => 'Requests waiting for your decision and their history.', 'body' => "Each request shows who sent it, what it asks for and which level of the flow it is in.\n\n- Approve or reject with a reason.\n- Filter by type or status to find an earlier request."],
    'pantalla-exportaciones' => ['title' => 'My exports', 'summary' => 'CSV, Excel or PDF files of the lists you exported.', 'body' => "From a list (employees, users, companies) use Export and choose CSV, Excel or PDF. The file only has the columns and rows you can see.\n\nIf the list is large, the export is prepared in the background: you can keep working and you get a notice when it is ready. Here you see its status and download it while it is valid."],
    'pantalla-tareas' => ['title' => 'Tasks', 'summary' => 'Internal to-dos with an owner and due date.', 'body' => 'Create tasks for yourself, for another person or for a role. Overdue tasks are highlighted so they are not missed.'],
    'pantalla-calendario' => ['title' => 'Calendar', 'summary' => 'Holidays, vacations and absences in one view.', 'body' => 'The calendar shows company holidays and the approved vacations and absences of the people you can see.'],
    'pantalla-seguridad-cuenta' => ['title' => 'Account security', 'summary' => 'Password, second factor and open sessions.', 'body' => 'Change your password, turn on the second factor and check which devices are signed in. If you do not recognize a session, close it here.'],
    'pantalla-mis-notificaciones' => ['title' => 'My notifications', 'summary' => 'Which channel each notice uses.', 'body' => 'Choose whether each type of notice reaches you in the system, by email or by message. Mandatory notices cannot be turned off.'],
    'pantalla-primeros-pasos' => ['title' => 'Getting started', 'summary' => 'Guided list to get your organization ready.', 'body' => "Getting started shows what is still missing before you use GestiaHR: company, country templates, sites, structure, jobs, employees, users, vacation policies and approval flows.\n\nEach step opens the screen where it is done and is marked complete once the data exists. You can skip a step and resume it later."],
    'pantalla-ayuda-organizacion' => ['title' => 'Your organization help', 'summary' => 'Your own articles and policies, and help usage.', 'body' => "Publish the internal rules or your policies to the right audience (roles, companies or sites), with an owner and a review date. Each publication is kept as a version.\n\nAs the review date approaches, the owner is notified and the article is marked for review while staying visible. In Help usage you see searches without results and how each article is rated."],
    'pantalla-asistente-ayuda' => ['title' => 'Help assistant', 'summary' => 'Activation, roles, question limit, quality and AI log.', 'body' => "The help assistant answers in natural language using only the help center articles each person can open, and always cites its sources. It does not query employee data or take actions.\n\nTurn it on, choose which roles see it and, optionally, a question limit per person and a notice. If your plan does not include it, the screen says so and it cannot be turned on.\n\nQuality shows the questions that found no article (so you can write it) and badly rated answers. The AI log records each use: who, when, what for and how many sources were cited, without showing the content."],
    'pantalla-constructor-flujos' => ['title' => 'Flow builder', 'summary' => 'Design flows with nodes, test them with a sample case and publish them.', 'body' => "The builder lays out a flow on the canvas: a start with the event that triggers it, conditions with “yes” and “no” exits, approvals, tasks, notices, waits and an end.\n\nThe draft is saved even when unfinished. To publish, every node must be connected and have an exit. Use “Test” with sample data to see the path without creating anything. Publishing again creates a new version and anything already running keeps the previous one."],
    'pantalla-configuracion' => ['title' => 'Settings', 'summary' => 'Users, roles, flows, parameters and catalogs.', 'body' => "Settings groups what defines how your organization works in GestiaHR. You only see the sections your role can manage.\n\nChanges are kept in the audit log with the old and new value."],
    'pantalla-organizacion' => ['title' => 'Organization', 'summary' => 'Companies, sites, units, jobs and cost centers.', 'body' => 'This is where you define the structure used by employee profiles. Structure changes have an effective date and can be scheduled.'],
    'pantalla-empresas' => ['title' => 'Companies', 'summary' => 'The group\'s legal entities and their labor regime.', 'body' => 'Register each company with its tax ID, address and labor regime. The regime is effective-dated: if it changes, the previous one is closed and the new one starts on its date.'],
    'pantalla-posiciones' => ['title' => 'Positions and headcount', 'summary' => 'Approved positions, vacancies and headcount budget.', 'body' => "Positions are the seats of the structure. A new seat is requested with a position request and goes through approval.\n\nThe headcount board compares approved positions with occupied ones."],
    'pantalla-colaboradores' => ['title' => 'Employees', 'summary' => 'The list of people and access to their profile.', 'body' => "Search by name, document or code and filter by company, site or status. From the profile you view and record everything about the person.\n\nTo register a hire use «Create → Employee»."],
    'pantalla-directorio' => ['title' => 'Directory', 'summary' => 'Find your colleagues and how to reach them.', 'body' => 'The directory shows work contact data: job, unit, site and manager. It does not include personal or sensitive data.'],
    'pantalla-organigrama' => ['title' => 'Org chart', 'summary' => 'The structure by people or by positions.', 'body' => 'Switch between the people view and the positions view. In the positions view, seats without an occupant show their status.'],
    'pantalla-contratos' => ['title' => 'Contracts', 'summary' => 'Contracts, renewals and addenda.', 'body' => 'Each contract goes through review, approval and signature. Those about to expire are highlighted so you can decide on renewal in time.'],
    'pantalla-movimientos' => ['title' => 'Personnel movements', 'summary' => 'Changes of job, manager, unit or site with an effective date.', 'body' => 'A movement closes the current assignment and opens a new one from its date. Future movements are scheduled and can be cancelled before they apply.'],
    'pantalla-cambios-de-datos' => ['title' => 'Data change requests', 'summary' => 'Corrections employees asked for from their portal.', 'body' => 'Review each request, compare it with the current value and approve or reject it with a reason.'],
    'pantalla-escenarios' => ['title' => 'Headcount scenarios', 'summary' => 'Simulate seat changes without touching real positions.', 'body' => "A scenario copies the positions in force on a date. You can add new seats, freeze or remove positions, and compare up to four scenarios by seats and cost.\n\nNothing changes in the real structure until the scenario is approved and applied: then draft position requests are created and the marked positions are frozen or closed."],
    'pantalla-firmas' => ['title' => 'Signatures', 'summary' => 'Signature requests and their evidence.', 'body' => "Send a file document for signature: choose the signers and their order. Each signer is notified, opens the document and signs with a one-time code.\n\nContracts, their addenda and remote-work agreements are signed with the provider's digital certificate; the rest with GestiaHR electronic signature. The evidence (document fingerprint, date, IP and code) is chained and cannot be altered."],
    'pantalla-mis-firmas' => ['title' => 'My signatures', 'summary' => 'Documents to sign.', 'body' => 'Here you see the documents you must sign. Open it, request your code (sent to your email or mobile) and enter it to sign. If something is wrong, decline with the reason.'],
    'pantalla-renovaciones' => ['title' => 'Renewals', 'summary' => 'Bulk renewal with signature.', 'body' => "Choose expiring contracts and the new end date. GestiaHR checks each one's accumulated limit: the one that exceeds it is left out with the explanation. When sent, each renewal is generated from its template and sent for signature; the batch shows progress per contract."],
    'pantalla-teletrabajo' => ['title' => 'Remote work', 'summary' => 'Remote work requests and agreements.', 'body' => "Register the request to change modality: the system calculates the legal response deadline in working days and warns before it expires.\n\nOnce approved, complete the minimum content of the agreement (modality, working hours, digital disconnection, place, supervision, equipment and expense compensation), issue it and register the signed copy."],
    'pantalla-constancias' => ['title' => 'Certificates', 'summary' => 'Certificates requested by employees.', 'body' => 'Issue or reject the certificates that are not issued automatically. The issued certificate is filed and visible to the employee.'],
    'pantalla-solicitudes-rrhh' => ['title' => 'Requests to Human Resources', 'summary' => 'Questions and requests coming from the portal.', 'body' => 'Handle each request, ask for information if something is missing and resolve it. Internal notes are only visible to Human Resources.'],
    'pantalla-mi-equipo' => ['title' => 'My team', 'summary' => 'The people who report to you and what they need.', 'body' => 'See your direct and indirect team, their pending requests and their key dates.'],
    'pantalla-vencimientos' => ['title' => 'Document expiry', 'summary' => 'Documents about to expire or already expired.', 'body' => 'Check which file documents are about to expire and request their renewal in time.'],
    'pantalla-solicitudes-documentos' => ['title' => 'Document requests', 'summary' => 'Ask one or several people for documents.', 'body' => 'Choose the document type, who you are asking and the due date. What they submit is reviewed in Approvals.'],
    'pantalla-plantillas' => ['title' => 'Document templates', 'summary' => 'Templates with variables to generate PDF documents.', 'body' => "A template uses variables filled with each person's data. Check it with the preview before publishing."],
    'pantalla-vacaciones' => ['title' => 'Vacations', 'summary' => 'Requests, balances and vacation records.', 'body' => 'See the balances and requests of the people you can view. The balance is calculated by the system from the policy in force.'],
    'pantalla-ausencias' => ['title' => 'Absences', 'summary' => 'Permissions, statutory leave and medical leave.', 'body' => 'Record or review absences by type. Some types require supporting documents and others open a subsidy case.'],
    'pantalla-programacion-vacaciones' => ['title' => 'Annual vacation schedule', 'summary' => 'Annual schedule and accumulated vacation.', 'body' => "HR opens the vacation schedule for a company and a year and proposes dates to each person. Each employee confirms or declines theirs; confirmed dates become approved requests under the same balance rules.\n\nBelow you see who has periods with balance, since when and which ones expire soon. The schedule can be exported."],
    'pantalla-acuerdos-vacaciones' => ['title' => 'Vacation agreements', 'summary' => 'Splitting, advance and sale of days with a signed document.', 'body' => "Each agreement is issued as a PDF in the employee file and becomes active when the signed copy is recorded. A signed sale takes the days off the balance and leaves the payroll concept.\n\nLimits come from the policy and the law: while the legal limit is pending validation, the agreement cannot be recorded."],
    'pantalla-calculos-planilla' => ['title' => 'Payroll calculations', 'summary' => 'Progress of each calculation and how each amount was obtained.', 'body' => 'Follow payroll calculations, which run in the background: progress updates by itself and one person with an error does not stop the rest. Pick a calculation to see the result per person and, for each concept, «How was it calculated?»: the formula, the data, the parameters in force and, if the regime changed during the month, each segment. A failed calculation can be resumed without repeating what was done. Differences from closed periods show as «Retroactive» with their origin period.'],
    'pantalla-revision-planilla' => ['title' => 'Payroll review', 'summary' => 'Comparison with the previous period, explained anomalies and simulation.', 'body' => "Before submitting the payroll for approval, compare it with the previous period: each person's net pay, the variation and whether it exceeds the company or concept threshold. Each anomaly comes with its explanation and the concepts that cause it; review or dismiss it with a note. If anomalies remain open, submitting asks you to confirm them, and an open critical anomaly prevents closing the period.\n\n«Simulate» calculates the period without saving the result: use it to test a parameter change or an incident before the real calculation."],
    'pantalla-boletas' => ['title' => 'Payslips', 'summary' => 'Generate, publish and track delivery of the period\'s payslips.', 'body' => "With the period approved or closed, «Generate payslips» issues one per worker from the current calculation and stores its PDF in the employee file. If your organization has it set up, payslips are published automatically when the period closes; otherwise «Publish all» puts them in the portal and notifies each person.\n\nEach row shows the delivery record: published, viewed, acknowledged or handed over in print with the scanned receipt. An issued payslip is never changed or deleted: to correct it, void it with a reason and the new version references it. Bulk download is delivered through a temporary link and is logged. «Why it changed» explains the net pay difference against the previous payslip."],
    'pantalla-mis-boletas' => ['title' => 'My payslips', 'summary' => 'Your payslips, their details and download.', 'body' => 'Here are your payslips for all your periods. Open them to see earnings and deductions or download them as PDF. If your company asks you to confirm receipt, use «Confirm receipt». «Why did my net pay change?» shows which concepts changed against the previous payslip.'],
    'pantalla-beneficios-sociales' => ['title' => 'Social benefits', 'summary' => 'Severance (CTS) deposits and profit sharing.', 'body' => "July and December bonuses and severance (CTS) are calculated as payroll periods of their kind: the system takes the computable months of the half-year, the computable pay and, for CTS, one sixth of the last bonus. Workers without a registered CTS account end with an error and are not deposited until it is added to their record.\n\nIn «CTS deposits» choose the CTS period, review each deposit and register the bank date and reference: the deposit statement is filed and published in the worker portal.\n\nIn «Profit sharing» register the declared net income for the fiscal year and the company activity, calculate the distribution (one part by days worked and one by pay, terminated workers included) and approve it; the profit-sharing payroll period takes the assigned amount. Rates and the cap are legal parameters: if one is «to be validated», review it with your accountant before approving."],
    'pantalla-liquidaciones' => ['title' => 'Settlements', 'summary' => 'Social benefits settlement at termination, its approval, payment and documents.', 'body' => "Registering a termination creates its settlement in draft. «Calculate» builds the prorated items (bonus and its extraordinary bonus, CTS, vacation), earned unused vacation and, if you mark it applies, the dismissal indemnity with the regime cap. Each line explains the time it took; the formula and parameters stay in the trace. Loan and advance balances are deducted up to the cap and the remainder is recorded.\n\nSubmit it for approval: someone other than who calculated it approves it and from then on it does not change. The payment deadline is a legal parameter: if it is «to be validated» you will see no due date; if it has a value, the system alerts before it expires. Recording the payment issues the settlement statement, employment certificate, CTS release letter and termination record; send them for signature and, once signed, deliver them: they appear in the former employee's portal.\n\nThe simulator calculates one or two termination dates without registering anything; only the access is logged."],
    'pantalla-pagos-planilla' => ['title' => 'Payroll payments', 'summary' => 'Batches per bank, bank file, confirmation and paid payroll.', 'body' => "With the period closed, «Prepare batches» groups each person's net pay by bank using the salary account in force on the payment date. People without an account are listed apart to be paid another way, and the summary shows that batches and pending amounts match the payroll net.\n\nGenerate the batch file, download it and upload it to your bank; then confirm the batch with the transaction reference. When all batches are confirmed, «Mark as paid» sets the period as paid. An unconfirmed batch can be cancelled with a reason. Each bank's file layout is validated with the bank before use."],
    'pantalla-retenciones-quinta' => ['title' => 'Fifth-category withholdings', 'summary' => 'Withholding ledger of the year, per-employee summary and reconciliation with payslips.', 'body' => "Each calculation leaves an entry in the ledger, which is never edited or deleted: a recalculation is a new sequence and the one from a discarded run stays visible. An employee's summary shows the withholding in force for each month, its running total and the balances brought from the previous system with their cut-off date.\n\nThe reconciliation compares what was withheld on the payslips of closed periods with the ledger; if it does not match, review the period before filing. Year-to-date balances from a previous system are brought in with the «Payroll year-to-date balances» import before the first close."],
    'pantalla-declaraciones' => ['title' => 'Filings', 'summary' => 'PLAME, T-Registro, AFPnet, bank templates and fifth-category certificates.', 'body' => "Create the filing for the company and period, then validate it: the system builds the files with the country pack layouts and lists the errors per worker (concepts without a table 22 code, missing labor registry data, totals that do not match the closed payroll). Each generated file keeps its fingerprint, author and date.\n\nWhile the period is not closed or the layout is not verified, the file is a draft and cannot be marked as submitted. Your company submits in the official tool and here you record the order number, the response (accepted or observed) and, if needed, the rectification. In T-Registro you see pending registrations and terminations with their deadline; in AFPnet, the due date and the reconciliation with the settlement. Fifth-category certificates come from the withholding ledger and are published in the portal."],
    'pantalla-bitacora-declaraciones' => ['title' => 'Filing log', 'summary' => 'What is still to be filed per company and period, with owner and payment.', 'body' => "For each company and period you see the filings that apply: the electronic payroll if there were workers, pension contributions if anyone is in a private fund, and the labor registry if there were changes. Missing ones are listed as missing.\n\nEach filing shows its status (generated, submitted, paid or rectified), due date and owner. When the company pays, record the receipt number here: the filing is marked paid without changing its submission status."],
    'pantalla-registro-laboral' => ['title' => 'Labor registry', 'summary' => 'T-Registro profile with validity and pre-registration checks.', 'body' => "The profile keeps the labor registry data that is not in the employee file (worker type, occupation, education, payment type, insurance). Each change creates a new row with its date and, if the worker is already registered, the update notice with its deadline.\n\n«Validate» runs the pre-registration checks and lists each missing item with a link to the screen where it is fixed. While anything is missing the profile stays blocked and is not included in the registration file."],
    'pantalla-devoluciones-quinta' => ['title' => 'Fifth-category refunds', 'summary' => 'Excess withholding to refund, offset or request from the tax authority.', 'body' => "The excess comes from the withholding ledger (termination adjustment or December true-up) or from the worker declaration. Whoever records the refund cannot approve it: another person approves it and it is posted to the ledger.\n\nThe refunded amount is offset against the period withholdings; if that is not enough, the balance carries over to the next period or is requested from the tax authority with its reference. It is closed with a zero balance or with the request recorded."],
    'pantalla-rentas-otros-empleadores' => ['title' => 'Income from other employers', 'summary' => 'Declare what you earned or earn with another employer this year.', 'body' => "If you worked for another employer this year or work for two at the same time, declare what they paid you and what they withheld. HR validates it and from that month the fifth-category withholding takes it into account; closed months are not recalculated.\n\nIf you declare nothing, withholding is calculated only with what this company pays you. A new declaration from the same employer replaces the previous one without deleting it."],
    'pantalla-micro-pequena-empresa' => ['title' => 'Micro and small business', 'summary' => 'Accreditation, sales in UIT and permanence in the regime.', 'body' => "Record each year the company's net sales and the UIT of the fiscal year. The system compares sales with the regime cap and warns the first year over it; after the consecutive years required by law it marks the permanence with its end date. Only people hired after the accreditation inherit the special regime. When the permanence ends, use the mass change with an effective date."],
    'pantalla-planilla-periodos' => ['title' => 'Payroll periods', 'summary' => 'Open the period, load incidents and take absences up to the cut-off.', 'body' => "Each period belongs to a payroll group (company, frequency and currency) and moves only through actions: open, incidents closed, calculated, in review, approved, closed and paid. A period cannot be opened while the previous one of the same kind is not closed.\n\nIncidents are the only way variable values (bonuses, commissions, deductions) reach the calculation. Manual ones above the approval amount wait for approval; those coming from absences or vacations are corrected at their source. They are locked when the period is sent for approval.\n\n«Take absences» reads each person's summary up to the cut-off date and records the cut-off; anything that happens later enters the next period as a difference. Whoever calculated or loaded incidents cannot approve the period."],
    'pantalla-parametros-legales' => ['title' => 'Legal parameters', 'summary' => 'Country legal values with their rule, pension fund tables and regulatory updates.', 'body' => "Here you see the legal values payroll uses (tax unit, minimum wage, rates, deadlines and tables) with the date they apply from and the rule behind them. GestiaHR maintains them: the organization does not edit them.\n\nWhere the law allows it you can set a more favorable own value. A value pending validation is used in simulations, but before a period is closed the payroll owner confirms it. Updates lists each published change and the periods it touches: open ones are simulated and closed ones are not recalculated."],
    'pantalla-resumen-periodo' => ['title' => 'Period summary', 'summary' => 'What payroll will take from absences, day by day.', 'body' => "Pick the person and the period to see each day explained: worked, remote, rest day, holiday or absence with its effect (paid, unpaid, paid by the employer or subsidized).\n\nRemote days are not absences. Closing the period freezes the summary: if anything changes later, you will see the difference here."],
    'pantalla-conceptos-planilla' => ['title' => 'Payroll concepts', 'summary' => 'Earnings, deductions and contributions with their formula, bases and accounts.', 'body' => "Each concept has a formula and, when needed, a condition. Changes are saved as a draft, reviewed, tested on a real person and published with an effective date: the previous version stays in the history.\n\nThe bases it affects say which calculation bases the concept adds to (health, pension, income tax, severance fund, bonuses). Country pack concepts come with their bases and statutory codes; those marked «to be validated» should be checked with your accountant. Legal values come from parameters, never from the formula."],
    'pantalla-subsidios' => ['title' => 'Subsidies', 'summary' => 'Follow-up of subsidy cases.', 'body' => 'Each case shows its status, from filing to reimbursement. Record each step so the follow-up is not lost.'],
    'pantalla-portal' => ['title' => 'Your portal', 'summary' => 'Your data, documents and requests.', 'body' => 'From the portal you see your information and handle your requests to Human Resources, also from your phone.'],
    'pantalla-mis-documentos' => ['title' => 'My documents', 'summary' => 'The documents the company published for you.', 'body' => 'Here you find your current contract, your certificates and the documents you were asked to submit.'],
    'pantalla-mi-perfil' => ['title' => 'My profile', 'summary' => 'Your personal and work data.', 'body' => 'If something is not right, request the change: Human Resources reviews it before applying it.'],
    'pantalla-mis-tramites' => ['title' => 'My requests', 'summary' => 'Certificates and requests to Human Resources.', 'body' => 'Request a certificate or send a question and follow its status. You will be notified when there is an answer.'],
    'campo.time.vacations.dates' => ['title' => 'Vacation dates', 'summary' => 'How days are counted.', 'body' => 'Choose the first and last day off. Before you send the request, the system shows how many days will be deducted from your balance under the policy in force.'],
    'campo.time.absences.absence_type' => ['title' => 'Absence type', 'summary' => 'Which type to choose.', 'body' => "The type defines whether the absence is paid, whether it requires supporting documents and who approves it. If in doubt, check your company's policy or ask Human Resources."],
    'campo.documents.requests.due_on' => ['title' => 'Due date', 'summary' => 'Until when it can be submitted.', 'body' => 'The person sees the date in their portal. After it passes, the request stays open and is highlighted as overdue.'],
    'campo.portal.requests.category' => ['title' => 'Request type', 'summary' => 'So it reaches the right people.', 'body' => 'The type decides who handles your request and whether you must attach a file.'],
    'recorrido.admin_empresa' => ['title' => 'Administrator tour', 'summary' => 'The essentials to get your organization ready.', 'body' => "Getting started: on Home you will find the guided list to set up company, sites, structure and employees. Each step takes you to its screen.\n\nSettings: users, roles, approval flows, parameters and your organization help live here.\n\nHelp: the help button in the top bar explains each screen. If something is unclear, you can write to GestiaHR support from there."],
    'recorrido.rrhh' => ['title' => 'Human Resources tour', 'summary' => 'Where your day-to-day work is.', 'body' => "People: each employee record gathers data, contracts, history, documents and vacations.\n\nInbox and approvals: what waits for your decision shows in the Inbox; portal requests arrive at People → Requests.\n\nYour organization help: publish your policies in Settings → Help and assistant so everyone finds them in help."],
    'recorrido.payroll' => ['title' => 'Payroll tour', 'summary' => 'What you can already review while payroll is being enabled.', 'body' => "Employees: review regime, current salary, pension and bank account on each record.\n\nAbsences and vacations: what is approved is recorded with its dates for the payroll period.\n\nHelp: the help button explains each screen and its fields."],
    'recorrido.recruiter' => ['title' => 'Recruiting tour', 'summary' => 'To start filling positions.', 'body' => "Positions: approved and vacant positions are in Organization → Positions.\n\nPosition requests: ask for a new position there and follow its approval.\n\nHelp: the help button explains each screen."],
    'recorrido.manager' => ['title' => 'Manager tour', 'summary' => 'Your team in one place.', 'body' => "My team: see your people, their key dates and who is on vacation.\n\nTeam requests: approve or reject vacations, absences and movements from My team → Requests.\n\nHelp: if a screen is unclear, open help or send your question to Human Resources."],
    'recorrido.empleado' => ['title' => 'Your portal tour', 'summary' => 'What you can do from your phone.', 'body' => "Your portal: see your data, documents and vacation balance.\n\nRequests: ask for vacations or certificates, or send a request to Human Resources and follow its status.\n\nHelp: the help button answers common questions and your company policies. If that is not enough, send your question to Human Resources."],
    'recorrido.auditor' => ['title' => 'Auditor tour', 'summary' => 'Review without changing anything.', 'body' => "Read-only: you can review records, documents and movements according to your permissions; you cannot change them.\n\nAudit: every sensitive change is recorded with who, when, and the old and new value.\n\nHelp: the help button explains each screen."],
    'recorrido.sst' => ['title' => 'Health and safety tour', 'summary' => 'To get started with your area.', 'body' => "Employees and sites: check where each person works and their job.\n\nDocuments: document expirations tell you what must be renewed.\n\nHelp: the help button explains each screen."],
    'recorrido.investigador_denuncias' => ['title' => 'Investigator tour', 'summary' => 'Your access is restricted.', 'body' => "You only see the cases assigned to you; nothing else in the organization.\n\nEvery read of a case is recorded.\n\nHelp: the help button explains each screen."],
    'recorrido.contador' => ['title' => 'Accountant tour', 'summary' => 'Read-only access.', 'body' => "You can review the accounting information the organization shares with you, without changing it.\n\nEvery lookup and export is recorded.\n\nHelp: the help button explains each screen."],
    'novedades.1-0.base' => ['title' => 'What is new in 1.0 · Platform', 'summary' => 'Security, approvals and help.', 'body' => "- Sign-in with a second factor and with an ID document.\n- Approval flows, tasks and notifications by email, SMS and WhatsApp.\n- Help center on every screen, with tours by role."],
    'novedades.1-0.core' => ['title' => 'What is new in 1.0 · People management', 'summary' => 'Records, contracts, documents and portal.', 'body' => "- Employee record with history, compensation and contracts.\n- Digital file, templates and PDF certificates.\n- Employee and manager portal, and import from Excel."],
    'novedades.1-0.time_off' => ['title' => 'What is new in 1.0 · Time off', 'summary' => 'Balances, requests and calendar.', 'body' => "- Vacation policies and balances by regime.\n- Requests with approval and a team calendar.\n- Absences, medical leave and statutory leave."],
];
